CREATE OR REPLACE FUNCTION public.service_occupation(_value text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT CASE lower(trim(coalesce(_value,''))) WHEN 'ఎలక్ట్రీషియన్' THEN 'electrician' WHEN 'ఎలక్ట్రిషియన్' THEN 'electrician' WHEN 'electrition' THEN 'electrician' WHEN 'ప్లంబర్' THEN 'plumber' WHEN 'టెక్నీషియన్' THEN 'technician' WHEN 'టీవీ మెకానిక్' THEN 'tv mechanic' ELSE lower(trim(coalesce(_value,''))) END $$;
CREATE TABLE public.service_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id),service text NOT NULL,area text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.service_requests TO service_role;
ALTER TABLE public.service_requests ENABLE ROW LEVEL SECURITY;
CREATE INDEX service_requests_area ON public.service_requests(area,created_at DESC);
CREATE TABLE public.service_request_pairs(request_id uuid NOT NULL REFERENCES public.service_requests(id) ON DELETE CASCADE,member_id uuid NOT NULL REFERENCES public.profiles(id),owner_id uuid NOT NULL REFERENCES public.profiles(id),PRIMARY KEY(request_id,member_id));
GRANT ALL ON public.service_request_pairs TO service_role;
ALTER TABLE public.service_request_pairs ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.service_chat_presence(member_id uuid NOT NULL REFERENCES public.profiles(id),owner_id uuid NOT NULL REFERENCES public.profiles(id),member_opened boolean NOT NULL DEFAULT false,owner_opened boolean NOT NULL DEFAULT false,PRIMARY KEY(member_id,owner_id));
GRANT ALL ON public.service_chat_presence TO service_role;
ALTER TABLE public.service_chat_presence ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.public_service_requests(_area text) RETURNS TABLE(id uuid,service text,area text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT r.id,r.service,r.area FROM public.service_requests r WHERE trim(_area)<>'' AND lower(trim(r.area))=lower(trim(_area)) AND public.account_allowed(r.user_id) AND r.created_at>now()-interval '1 month' ORDER BY r.created_at DESC LIMIT 200 $$;
REVOKE ALL ON FUNCTION public.public_service_requests(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.public_service_requests(text) TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.request_service(_service text,_area text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE rid uuid; who record; caller uuid:=auth.uid(); BEGIN IF caller IS NULL OR NOT public.account_allowed(caller) THEN RAISE EXCEPTION 'SIGN_IN_REQUIRED'; END IF; IF NOT public.has_paid_bell(caller) THEN RAISE EXCEPTION 'PAID_BELL_REQUIRED'; END IF; IF public.service_occupation(_service) NOT IN('electrician','plumber','technician','tv mechanic') OR length(trim(_area)) NOT BETWEEN 1 AND 80 THEN RAISE EXCEPTION 'SERVICE_AREA_REQUIRED'; END IF; PERFORM 1 FROM public.profiles WHERE id=caller FOR UPDATE; SELECT id INTO rid FROM public.service_requests WHERE user_id=caller AND service=public.service_occupation(_service) AND lower(trim(area))=lower(trim(_area)) AND created_at>now()-interval '5 minutes' LIMIT 1; IF rid IS NOT NULL THEN RETURN rid; END IF; INSERT INTO public.service_requests(user_id,service,area) VALUES(caller,public.service_occupation(_service),trim(_area)) RETURNING id INTO rid; FOR who IN SELECT user_id FROM public.service_profiles WHERE published AND public.service_occupation(coalesce(nullif(category,''),service))=public.service_occupation(_service) AND lower(trim(town))=lower(trim(_area)) UNION SELECT user_id FROM public.posts WHERE module='job' AND service_type='service' AND kind='employer' AND status='active' AND (visible_after IS NULL OR visible_after<=now()) AND (job_expires_at IS NULL OR job_expires_at>now()) AND public.service_occupation(skill)=public.service_occupation(_service) AND lower(trim(location))=lower(trim(_area)) LOOP IF who.user_id<>caller AND public.has_paid_bell(who.user_id) AND public.account_allowed(who.user_id) THEN PERFORM 1 FROM public.profiles WHERE id=who.user_id FOR UPDATE; INSERT INTO public.notifications(user_id,message) VALUES(who.user_id,'మీ ప్రాంతంలో మీ సేవ కోరారు; సేవల అభ్యర్థనల పేజీలో చూడండి.'); END IF; END LOOP; RETURN rid; END $$;
REVOKE ALL ON FUNCTION public.request_service(text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.request_service(text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.respond_service_request(_request uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.service_requests; caller uuid:=auth.uid(); BEGIN IF caller IS NULL OR NOT public.account_allowed(caller) THEN RAISE EXCEPTION 'SIGN_IN_REQUIRED'; END IF; IF NOT public.has_paid_bell(caller) THEN RAISE EXCEPTION 'PAID_BELL_REQUIRED'; END IF; SELECT * INTO r FROM public.service_requests WHERE id=_request AND created_at>now()-interval '1 month'; IF r.id IS NULL OR r.user_id=caller OR NOT public.account_allowed(r.user_id) THEN RAISE EXCEPTION 'SERVICE_UNAVAILABLE'; END IF; INSERT INTO public.service_request_pairs VALUES(r.id,caller,r.user_id) ON CONFLICT DO NOTHING; INSERT INTO public.service_chat_presence(member_id,owner_id) VALUES(caller,r.user_id) ON CONFLICT DO NOTHING; INSERT INTO public.messages(sender_id,receiver_id,body) VALUES(caller,r.user_id,'హాయ్ · Hi'); PERFORM 1 FROM public.profiles WHERE id=r.user_id FOR UPDATE; INSERT INTO public.notifications(user_id,message) VALUES(r.user_id,'మీ సేవ అభ్యర్థనకు స్పందన వచ్చింది; సంభాషణలో చూడండి.'); RETURN r.user_id; END $$;
REVOKE ALL ON FUNCTION public.respond_service_request(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.respond_service_request(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.can_post_chat(_post uuid DEFAULT NULL,_other uuid DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND auth.uid()<>_other AND public.account_allowed(auth.uid()) AND public.account_allowed(_other) AND CASE WHEN _other=public.support_admin_id() OR public.has_role(auth.uid(),'admin') THEN true WHEN NOT public.has_paid_bell(auth.uid()) THEN false WHEN _post IS NULL THEN EXISTS(SELECT 1 FROM public.service_request_pairs WHERE (member_id=auth.uid() AND owner_id=_other) OR (owner_id=auth.uid() AND member_id=_other)) OR EXISTS(SELECT 1 FROM public.service_chat_pairs WHERE (member_id=auth.uid() AND owner_id=_other) OR (owner_id=auth.uid() AND member_id=_other)) OR EXISTS(SELECT 1 FROM public.messages WHERE post_id IS NULL AND ((sender_id=auth.uid() AND receiver_id=_other) OR (receiver_id=auth.uid() AND sender_id=_other))) ELSE EXISTS(SELECT 1 FROM public.post_chat_pairs WHERE post_id=_post AND ((member_id=auth.uid() AND owner_id=_other) OR (owner_id=auth.uid() AND member_id=_other))) END $$;
CREATE OR REPLACE FUNCTION public.open_service_chat(_other uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.service_chat_presence; BEGIN SELECT * INTO p FROM public.service_chat_presence WHERE (member_id=auth.uid() AND owner_id=_other) OR (owner_id=auth.uid() AND member_id=_other); IF p.member_id IS NULL THEN RETURN true; END IF; IF NOT public.can_post_chat(NULL,_other) THEN RETURN false; END IF; UPDATE public.service_chat_presence SET member_opened=member_opened OR member_id=auth.uid(),owner_opened=owner_opened OR owner_id=auth.uid() WHERE member_id=p.member_id AND owner_id=p.owner_id RETURNING * INTO p; RETURN p.member_opened AND p.owner_opened; END $$;
REVOKE ALL ON FUNCTION public.open_service_chat(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.open_service_chat(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.guard_service_phone_exchange() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM public.service_chat_presence WHERE ((member_id=NEW.sender_id AND owner_id=NEW.receiver_id) OR (owner_id=NEW.sender_id AND member_id=NEW.receiver_id)) AND NOT(member_opened AND owner_opened)) AND (coalesce(NEW.chat_phone,'')<>'' OR coalesce(NEW.body,'') ~ '[0-9][0-9 ()+.-]{8,}[0-9]' OR coalesce(NEW.image_path,'')<>'') THEN RAISE EXCEPTION 'BOTH_MUST_OPEN_CHAT'; END IF; RETURN NEW; END $$;
CREATE TRIGGER service_phone_exchange BEFORE INSERT ON public.messages FOR EACH ROW EXECUTE FUNCTION public.guard_service_phone_exchange();